"""Detailed original teaching for Techniques of calculation, printed pp. 127–164.

Selected book positions were checked against the supplied PDF. Other examples
are explicitly labeled original illustrations. A shown legal defence is not
necessarily forced; the notes distinguish illustrative play from conclusions.
"""
from core.primer_build import after, custom
from core.primer_chapter4 import POSITIONS as P
from core.primer_guides_chapter1 import check, example, guide, section

GUIDES = {}


def _add(ident, pages, goals, sections, examples, pitfalls, checks, recap):
    GUIDES['ch4-' + ident] = guide(pages, goals,
        [section(title, body) for title, body in sections], examples,
        pitfalls, checks, recap)


_add('calculation-routine', (127,128),
 ('Recognize when exact calculation is useful.', 'Finish a line with an assessment and a final safety check.'),
 [
  ('Start with a question', '''Calculation means imagining legal moves without moving the pieces. Its purpose is to answer a question: can I win this pawn, can my king survive, or does this exchange lead to a favorable ending? Begin with whose turn it is, checks against either king, undefended pieces, and immediate threats. Then select a small set of plausible candidate moves. In a sharp position, checks, captures, and direct threats are useful candidates because they reduce the opponent's choices. They are a search order, not a command to play every check. A check that loses your queen may simply be bad.'''),
  ('Quiet positions need plans too', '''If the pieces are separated, both kings are safe, and nothing is immediately threatened, many replies may be equally reasonable. Trying to predict ten exact moves in such a position wastes effort. Ask what your least useful piece should do, which pawn break you want, and what changes when a piece leaves its old square. Still perform a short tactical check on your chosen improving move. The distinction is between using a plan to select candidates and using concrete calculation to check their safety; good play usually needs both, in proportions set by the position.'''),
  ('One branch at a time', '''Imagine your first candidate and the opponent's strongest reply, not their most convenient reply. Continue until the immediate exchanges or threats are resolved, then state the result: mate, a safe extra pawn, a drawn pawn ending, or an uncertain position requiring more thought. Return mentally to the starting board before examining the second candidate. Keep track of removed pieces and vacated squares. Compare the resulting assessments, not just the attractiveness of the first move. Finally check the selected line once more for a missed capture, check, or stronger defensive response.'''),
  ('A short line can outweigh a large threat', '''The original opening illustration contains White's queen on h5, bishop on c4, and Black's knight attacking the queen from f6. The threatened queen capture looks alarming, but White moves first and can mate on f7. Before advancing the replay, picture the queen on f7, remove the captured pawn, and inspect the king's possible captures and exits. The bishop's diagonal is the reason the king cannot take the queen. This is an exercise in priorities, not a recommendation to bring your queen out early in every opening. In your own games, ask whether the threat you fear arrives before or after your forcing move.'''),
 ],
 [example('Original illustration: the game ends before the queen can be taken', after(('e4','e5','Qh5','Nc6','Bc4')),
          ('Nf6','Qxf7#'), ('Black to move. Inventory: White has queen h5 and bishop c4 aimed at f7; both full armies remain except that no captures have occurred. Predict the forcing reply before advancing.',
          'The knight attacks the queen, but does not stop the mating threat on f7.',
          'The protected queen gives mate. The attack on h5 never gets a second turn.'))],
 ('Do not calculate only the reply you hope to see.', 'Do not stop after a capture without checking the new threats.'),
 [check('routine-stop','When is a useful point to stop calculating a tactical branch?',
        ('When the urgent sequence is resolved and you can evaluate the position',True,'A stable endpoint lets you compare alternatives meaningfully.'),
        ('Immediately after your first capture',False,'The opponent may recapture, check, or create a stronger threat.')),
  check('routine-quiet','What is sensible in a quiet position with several sound moves?',
        ('Choose a useful plan and tactically check its candidate moves',True,'A plan narrows the search; calculation checks the actual move.'),
        ('Predict one exact ten-move line and assume it will happen',False,'Quiet positions often allow many reasonable replies.'))],
 ('Name the question before calculating.','Evaluate one branch before switching.','Recheck the selected move for the opponent’s forcing replies.'))

_add('square-rule', (128,129),
 ('Draw the square of a freely advancing pawn.', 'Adjust the square for the player whose turn it is.'),
 [
  ('Build the square from the promotion distance', '''A white pawn on h3 needs five moves to reach h8 if it advances one square each time. Its square extends five steps toward the opposing king: h3-c3-c8-h8. The boundary counts as inside. In the simple race between that pawn and a king, a king already inside can catch it, provided its route is not blocked or attacked. You can visualize just the diagonal h3-c8 instead of all four sides. For a black pawn, reverse the direction: its destination is rank one. Count moves to promotion, not the number of printed rank labels.'''),
  ('Whose turn changes the test', '''When the defender is outside the square and moves next, it may be able to enter before the pawn advances. When the pawn moves next, redraw the smaller square after that move and test the king's reply against it. In our original illustration, Black's king is on c4 and White's pawn on h3. After h4 the square runs from d4 to h8. The king can enter at d5 and continue diagonally toward g7. An inattentive move away from the pawn can lose even though the original diagram was drawable.'''),
  ('The king need not follow the file', '''A king changes file and rank together with a diagonal move. It need not walk straight toward the pawn's current square and then turn upward. The catching route c4-d5-e6-f7-g7 aims at the place the pawn will reach later. At g7 the king controls h8. In the replay White still promotes so you can see the final capture; promotion itself does not prove a pawn has escaped. Before each arrow, say where the pawn will stand and which promotion or capture square the king must control on its next turn.'''),
  ('Use the shortcut within its limits', '''The clean rule assumes an unobstructed pawn and an enemy king without interference from other pieces. Our white king on a1 is deliberately far away, so it cannot escort h3 or cut the catching route. This makes the diagram a reliable first model. In a real ending, check for a friendly pawn occupying the king's route, an enemy piece attacking an entry square, a double pawn move, and the supporting king. These checks take much less effort than guessing a long race. The square is a fast first assessment; a concrete obstruction can require a different conclusion.'''),
 ],
 [example('Original illustration: a diagonal catches the runner', P['square'],
          ('h4','Kd5','h5','Ke6','h6','Kf7','h7','Kg7','h8=Q+','Kxh8'),
          ('White: king a1 and pawn h3. Black: king c4. Calculate whether d5 remains inside the square after h4.',
           'The pawn advances; its square shrinks to d4-h4-h8-d8.',
           'Black enters the reduced square diagonally.', 'The pawn continues toward h8.',
           'The king gains a file and a rank in one move.', 'The pawn has two moves left to promotion.',
           'The king approaches the control point g7.', 'The pawn threatens to promote next move.',
           'The king controls h8 and will be able to capture there.',
           'Promotion gives check, but the new queen is undefended.',
           'Black captures the queen. Only kings remain, so the race has ended in a draw.'))],
 ('The boundary belongs to the square.', 'Recompute after a pawn move; do not keep using the original larger square.'),
 [check('square-boundary','A king stands on the boundary of the relevant square. Is it inside?',
        ('Yes',True,'The boundary squares count; diagonal steps can be enough to catch the pawn.'),
        ('No, it must be strictly nearer the pawn',False,'Excluding the edge incorrectly turns some draws into apparent wins.')),
  check('square-promotion','Why does h8=Q+ not win in this replay?',
        ('Black can legally capture the unprotected queen',True,'The race must be calculated through the next capture.'),
        ('Pawns may not promote when giving check',False,'Promotion with check is legal, but it does not make the new piece immune.'))],
 ('Count the pawn’s moves to the last rank.','Include the boundary and the side to move.','Check the promotion square after promotion.'))

_add('square-exceptions', (129,131),
 ('Include the first double move in a pawn race.', 'Identify blockers and supporting pieces that invalidate a bare square test.'),
 [
  ('A starting pawn can save a move', '''A white pawn on h2 normally appears six ranks from promotion. If h3 and h4 are empty, however, h2-h4 is legal and it needs only five turns: h4, h5, h6, h7, h8. For counting purposes, its promotion time matches a pawn on h3. In the original illustration Black's king on b4 is too far away after h4. If White chooses h3 instead, the king can approach through c5 and enter the next square. The option to make a double move must be counted before drawing a conclusion from the pawn's starting rank.'''),
  ('A king cannot walk through its own army', '''The square rule describes distance, not permission to occupy every square. A friendly pawn can block the shortest catching diagonal; the king may have to go around it and lose the race. An enemy pawn can also deny a critical approach square without standing on it, because it attacks diagonally. For every imagined king step ask whether the square is empty or capturable, whether it is attacked, and whether the kings would become adjacent. A piece that seems to add material to the defending side may therefore make its king's task harder rather than easier.'''),
  ('The attacking king changes the problem', '''When the pawn's king is nearby, it may protect the pawn or its promotion square and drive away a king that lies inside the geometric square. Conversely, an extra bishop or rook may stop a pawn even when the king cannot catch it. The book uses exchanges and trapped pieces to show that this matters before the final pawn ending has actually arrived. Calculate the simplified board first: which king remains on which square, which pawn survives, and can an enemy piece still interfere? Do not assume that every exchange helps the side with the more advanced pawn.'''),
  ('Know when there is time for another job', '''Sometimes the enemy king is so far outside the square that pushing immediately is unnecessary. You may first stop a bishop from escaping, move your own king out of a future check, or remove another pawn. Such a delay requires an actual count: after spending the move, does the enemy gain entry or a useful block? In this lesson's replay we choose the direct sprint, so the only variable is the initial double move. Pause before h4 and count the shortest black route to a square controlling h8. After promotion, check that the king on f8 cannot capture the new queen two files away.'''),
 ],
 [example('Original illustration: the first double step decides the race', P['double'],
          ('h4','Kc5','h5','Kd6','h6','Ke7','h7','Kf8','h8=Q+'),
          ('White: king a1, pawn h2. Black: king b4. Both h3 and h4 are empty. Predict the result of h4 before revealing the moves.',
           'White uses the legal double step and saves one turn.',
           'Black approaches diagonally but is outside the reduced square.',
           'White keeps the pawn moving.', 'Black gains a file and rank but cannot recover the lost tempo.',
           'Only two pawn moves remain.', 'The king still needs time to reach g7.',
           'Promotion is threatened on the next turn.', 'Black reaches f8, which is too far from h8 to capture there.',
           'The queen arrives safely with check. This is a won queen-versus-king ending, not immediate mate.'))],
 ('A double move requires both intervening and destination squares to be empty.', 'Extra material can block a king’s route or change the promotion tactics.'),
 [check('double-time','How many turns does an unobstructed white h2-pawn need to reach h8?',
        ('Five if it begins h4',True,'The first turn covers two squares; the remaining four cover one each.'),
        ('Always six',False,'This overlooks the optional starting double move.')),
  check('double-block','A friendly pawn occupies the king’s only timely catching square. What should you do?',
        ('Recalculate the legal route',True,'Geometric distance cannot move a king onto a square occupied by its own piece.'),
        ('Trust the square rule without checking the route',False,'The unobstructed-race assumption has failed.'))],
 ('Count double moves before drawing the square.','Check occupancy and attacks on the route.','Evaluate the board that exchanges would actually leave.'))

_add('reti', (131,132),
 ('Find a diagonal king route with two purposes.', 'Use a counterthreat to gain time for defence.'),
 [
  ('Inventory before inspiration', '''In Réti's 1921 study, White has king h8 and pawn c6; Black has king a6 and pawn h5. White moves. A direct chase down the h-file appears hopeless because the pawn is too far ahead. Advancing c7 immediately also fails to solve White's problem: Black's king is near c8 and can stop it. Instead of choosing one task and abandoning the other, look for king moves that improve both. The diagonal from h8 through g7 and f6 approaches the h-pawn while also bringing the white king closer to supporting c6.'''),
  ('Make the defender spend time', '''After Kg7, Black has two broad plans: hurry the h-pawn or bring the king toward c6. Against the pawn sprint h4 and h3, White heads toward e7. The king then supports c7 and d7, so Black cannot win the white pawn without allowing promotion. If Black instead spends a move on ...Kb6, White gains time to approach the h-pawn through f6 and e5 while retaining the possibility of supporting c6. These are not independent miracles. Black's move toward one danger is a move not spent advancing or controlling the other.'''),
  ('A diagonal need not cost extra time', '''Human intuition often treats a detour as slower. On a chessboard, however, a king's diagonal step can reduce two distances at once. Count king moves using the larger of the file and rank changes on an empty board, then adjust for attacked squares. From h8 toward the central crossroads, a diagonal is doing useful work in both directions. This is why Kg7 is more flexible than Kh7. Do not memorize a zigzag without its targets: the useful route depends on the positions of both pawns and on which side must answer the immediate threat.'''),
  ('Predict the final board, not just the idea', '''Before advancing the replay at Ke7, imagine c7, Black's king on b7, and White's king reaching d7. Black promotes on h1, then White promotes on c8. Both sides obtain queens; the study's point is that White saves a position that first appeared lost. Black’s promotion does not give check, so White can answer with its own promotion. Reset and trace the alternative ...Kb6 branch in the notes: Kg7 Kb6, Kf6 h4, Ke5 h3, Kd6 h2, c7. For your own games, the transferable question is whether a defensive king move can simultaneously create a threat that forces the opponent to spend time.'''),
 ],
 [example('Réti 1921, book diagram 218: both pawns promote', P['reti'],
          ('Kg7','h4','Kf6','h3','Ke7','h2','c7','Kb7','Kd7','h1=Q','c8=Q+'),
          ('White: Kh8, c6. Black: Ka6, h5. White to move. Predict how a move toward the center could serve both pawns.',
           'The king approaches h5 and c6 at once.', 'Black chooses the pawn sprint rather than ...Kb6.',
           'White preserves both routes from f6.', 'The h-pawn advances, so White now relies on the counter-promotion.',
           'The king approaches d7, from which it can protect c8.', 'Black is one move from promotion.',
           'The white pawn threatens c8 too; Black cannot ignore it indefinitely.', 'The king approaches c7 but cannot capture it on this turn.',
           'White protects c7 and c8, so the black king cannot remove the pawn.',
           'Black promotes without check, leaving White free to answer.',
           'White promotes with check on the diagonal to b7. Both queens exist, so the one-sided pawn race has been neutralized.')),
  example('Réti: a king move gives White another useful tempo', P['reti'],
          ('Kg7','Kb6','Kf6','h4','Ke5','h3','Kd6','h2','c7'),
          ('Same study, different defensive plan. Before revealing ...Kb6, predict which white route becomes possible.',
           'The double-purpose approach begins.', 'Black spends a turn bringing its king toward c6.',
           'White threatens to move toward the h-pawn while retaining the other route.',
           'Black resumes advancing the pawn.', 'The king threatens to approach through f4 if Black delays again.',
           'Black pushes, so White switches to the support route.', 'The king now protects c7.',
           'Black threatens h1, but this is still not check.', 'White will promote as well; ...Kxc7 is illegal because d6 protects c7.'))],
 ('A drawing resource may depend on creating a threat, not merely chasing.', 'Do not call the two promotions simultaneous: they occur on consecutive turns.'),
 [check('reti-jobs','What are Kg7 and Kf6 trying to accomplish?',
        ('Approach h5 and approach support for c6',True,'The same route keeps two useful plans alive.'),
        ('Force the black king to capture h5',False,'The black king cannot capture its own pawn and is defending the other wing.')),
  check('reti-time','Why can ...Kb6 help White’s defence?',
        ('Black uses a turn without advancing h5',True,'White can spend that turn improving the king’s central position.'),
        ('A king move gives White an extra turn',False,'Turns still alternate; the benefit is what Black did not accomplish with its turn.'))],
 ('Look for a move with two useful destinations.','A counterthreat can buy defensive time.','Check whether promotion gives check.'))

_add('count-races', (132,134),
 ('Count every required action in a promotion race.', 'Separate a move count from the final tactical assessment.'),
 [
  ('Make a small ledger', '''Count your own route and the opponent's route separately. Include moves needed to capture a blocking pawn, moves needed to clear your king from the pawn's file, and the pawn's advances. Then put the two counts back into alternating turns. An equal total does not mean the promotions happen together: the side whose turn comes first promotes first. A difference of one move can still let both players promote on consecutive turns. This arithmetic saves effort, but it only answers when the queens appear. You must also ask what each new queen can do on arrival.'''),
  ('A king in front can become a traffic jam', '''Our original position has White's king on h5 and pawn h4, Black's king on a4 and pawn a5. Both kings are on their pawns' paths. White needs one king move off the h-file, followed by four pawn moves. Black needs one king move off the a-file, followed by four pawn moves. White begins, so White's queen appears first. Kh6 would look active, yet it leaves the king in the pawn's way and requires another clearing move later. Kg5 removes the obstruction immediately. The task is about efficient clearance, not about the king's general centralization.'''),
  ('Do not spend tempos casually', '''A spare pawn move elsewhere may feel useful because it gains space. In a race it is still one turn not spent on the main route. Sometimes that turn improves the final geometry, and sometimes it gives away the entire result. Count again rather than calling it harmless. The same applies to capturing an extra pawn that is not blocking your runner. In the book, the apparently faster destination is not always best because the opponent's corresponding race may be faster still. Compare the difference between the two clocks, not only the number attached to your own pawn.'''),
  ('Use the final diagram as a second test', '''In this replay both sides would need five moves to promote, but h8=Q controls a1 along the long diagonal. Black's pawn on a2 therefore cannot promote safely on its next turn. Count this as a tactical consequence after the arithmetic, not as a reason to change how you counted. Before advancing the final arrow, locate h8, a1, and every square between them. Black's king on b3 does not block the diagonal. This illustrates why king clearance squares matter too. A different king position could interrupt the line, give the newly promoted queen check, or create a skewer against the first queen.'''),
 ],
 [example('Original illustration: equal clocks, unequal promotion geometry', P['race'],
          ('Kg5','Kb3','h5','a4','h6','a3','h7','a2','h8=Q'),
          ('White: Kh5, h4. Black: Ka4, a5. White to move. Count one king clearance and four pushes for each side.',
           'White clears the h-file in one move.', 'Black clears the a-file in one move.',
           'The first pawn push begins.', 'Black starts its four-step pawn sprint.',
           'White has two pushes left.', 'Black also has two pushes left, but moves second.',
           'White threatens promotion next turn.', 'Black reaches a2 one turn behind.',
           'The new queen controls a1 along h8-g7-f6-e5-d4-c3-b2-a1. A black promotion can be captured.'))],
 ('Count clearing moves and captures as well as pushes.', 'Equal counts do not imply a draw.'),
 [check('count-clear','Why is Kg5 more efficient than Kh6 in this diagram?',
        ('Kg5 leaves the pawn’s whole file clear immediately',True,'Kh6 would still need a later move off the pawn’s path.'),
        ('A king move to the side does not use a turn',False,'Every king move uses a turn; the point is avoiding a second clearing move.')),
  check('count-equal','What must you inspect after equal promotion counts?',
        ('Checks, captures, blocked lines, and attacks by the new queens',True,'The endpoint can change the result of the apparent race.'),
        ('Nothing; equal counts guarantee a draw',False,'In this example the first queen controls the other promotion square.'))],
 ('Count the complete route.','Put counts back into alternating turns.','Draw the final queen lines.'))

_add('promotion-geometry', (133,135),
 ('Spot checks and skewers after promotion.', 'Choose king clearance squares with the final board in mind.'),
 [
  ('The new queen changes every line', '''Promotion creates a long-range piece at once. A new queen can check the king, capture the opposing new queen, or control the opponent's promotion square. If it gives check, the opponent must answer before advancing a pawn, even if that pawn was one step from promotion. This often turns a supposedly equal race into a decisive lead. Mark both promotion squares and both king squares when counting. The book's central warning is that promotion arithmetic and visualization belong together: a correct count attached to an incorrect final picture still produces an incorrect decision.'''),
  ('A skewer starts with the valuable piece in front', '''A skewer attacks a king along a line with another target behind it. Because the king must escape check, the target can be captured afterward. Our original demonstration starts with White's king on a4 and pawn b7, Black's king on h7 and pawn h2; Black moves. After both pawns promote, Black checks on a1. The king's shown reply Kb5 places it on the b-file in front of the queen on b8. Then ...Qb1+ makes the skewer explicit. Identify the whole line b1-b5-b8, not merely the checking square.'''),
  ('Calculate the first check and the follow-up', '''Do not stop your analysis when you see ...Qa1+. Ask where the king can go, whether the opponent can interpose a queen, and which target becomes exposed afterward. In the shown continuation White plays Ka6 after ...Qb1+, and Black takes b8. This is one legal demonstration of the motif; a full claim that a position is forced winning requires checking all the king replies, queen blocks, and queen captures. The board exercise deliberately asks for the specified b-file skewer. It does not ask you to prove that every other queen move loses.'''),
  ('Prevent the geometry before it exists', '''The best time to avoid a promotion skewer is often when choosing where your king clears the pawn's route several moves earlier. A square can be safe now but align the king and future queen later. Compare the promotion squares with the king's rank, file, and diagonals. If your opponent promotes first, ask which checking squares become available and whether they gain a vital tempo. Before advancing this replay beyond b8=Q, mentally place the black queen on a1 and trace the king's possible departures. Repeat the exercise from a safer king square to understand the reason for the danger, rather than memorizing the sequence.'''),
 ],
 [example('Original illustration: promotion followed by a skewer', P['geometry'],
          ('h1=Q','b8=Q','Qa1+','Kb5','Qb1+','Ka6','Qxb8'),
          ('White: Ka4, b7. Black: Kh7, h2. Black moves first. Predict a checking line after both promotions.',
           'Black promotes without check.', 'White also promotes; material alone looks balanced.',
           'The queen checks along the a-file.', 'This illustrative king reply places the king in front of b8 on the b-file.',
           'The second check skewers the king against the white queen.', 'The king leaves the file; this is a legal example reply.',
           'Black captures the exposed queen. The race must be evaluated beyond the instant of promotion.'))],
 ('A promotion with check interrupts the other player’s pawn sprint.', 'A displayed skewer line is not a substitute for checking alternative replies.'),
 [check('geometry-check','Your opponent promotes with check. Can you ignore it and promote your own pawn?',
        ('Only if your promotion itself legally answers the check',True,'Every move in check must remove the check; most pawn pushes will not.'),
        ('Yes, because promotion takes priority',False,'Promotion has no exemption from the check rule.')),
  check('geometry-king','Why can an early king clearing move decide a later race?',
        ('It may align the king with the promotion square and allow a skewer',True,'The final location of the king affects the new queen’s tactics.'),
        ('It changes how far a queen can move',False,'The queen’s movement stays the same; the placement of targets changes.'))],
 ('Locate both kings at the end of the count.','Search for the first queen check and its follow-up.','Avoid future alignment while choosing the king’s route.'))

_add('count-attacks', (135,136),
 ('Count legal captures rather than apparent lines.', 'Adjust exchanges for pins and unequal piece values.'),
 [
  ('Counting is a filter, not a verdict', '''When several pieces attack one pawn, you can save effort by first counting attackers and defenders. If the target is attacked twice and defended once, investigate a capture. If the numbers match, ask whether the exchanging pieces have comparable values. A queen and a pawn are each one attacker, but exchanging a queen for a defended pawn is usually disastrous. Counting narrows the calculation; it does not replace the move order. In the book's large exchange example, the numbers work only after the usable pieces, their values, and the final board have all been considered.'''),
  ('A pinned pawn may be an imaginary defender', '''Our original position contains White's king a1, rook e1 and pawn c4; Black has king e8, pawns e6 and d5, and knight b8. The rook pins e6 to the black king. The e6-pawn geometrically attacks d5, but ...exd5 would expose the king along the e-file, so it is illegal. After an illustrative rook move on the same file and ...Nc6, White can play cxd5. The knight on c6 attacks d4 and e5, not d5. Count actual destinations instead of assuming a nearby developed piece must defend the target.'''),
  ('Recount after each capture', '''A capture can uncover a rook, remove a defender, or free a pinned piece by changing the king's position. Therefore, do not use the same attacker count for every stage of the exchange. If Black moves its king off the e-file, the e6-pawn may become a genuine defender again. If the white rook leaves the file, the same thing happens. Before advancing cxd5, picture e6-d5 and ask exactly which line would then attack the king. The answer is why the capture works in the present position. A pin is a relationship among pieces, not a permanent label attached to the pawn.'''),
  ('Check the least expensive capture first', '''When several captures are possible, start by calculating a low-value attacker, but remain alert to exceptions such as checks, intermediate moves, and an overloaded defender. Track material only after the immediate sequence is finished. Say what was removed from each side and whether the remaining attacker can be captured. A queen that takes a pawn and is then exchanged for a rook has not won a pawn overall. In your own games, use a three-part question: how many usable attackers, how many usable defenders, and in what order can they exchange? Then inspect the resulting king safety and any newly opened lines.'''),
 ],
 [example('Original illustration: the pinned pawn cannot recapture', P['pin'], ('Re2','Nc6','cxd5'),
          ('White: Ka1, Re1, c4. Black: Ke8, Nb8, e6 and d5. Predict whether the apparent e6 defender may legally move.',
           'The rook stays on the e-file, so the pin remains.',
           'Black develops the knight. This illustrative move does not defend d5 or break the pin.',
           'White captures d5. ...exd5 would expose the king on e8 to the rook and is illegal.'))],
 ('A piece can attack a square geometrically yet be unable to capture legally.', 'Equal numbers are not equal material when the piece values differ.'),
 [check('attack-pin','Does the e6-pawn provide a legal recapture after cxd5?',
        ('No, its move would expose the king to the rook',True,'This is an absolute pin to the king.'),
        ('Yes, pawns always defend their diagonal squares for exchanges',False,'A move that leaves its own king in check is illegal.')),
  check('attack-value','One attacker and one defender are present. Is the capture automatically safe?',
        ('No; compare piece values and the capture order',True,'A queen taking a pawn defended by a rook may lose material.'),
        ('Yes, because the numbers are equal',False,'A numerical count ignores what each side actually gives up.'))],
 ('Count usable pieces.','Include values and capture order.','Recount after each removal or king move.'))

_add('exchange-traps', (136,137),
 ('See how exchanges open files and diagonals.', 'Check intermediate threats before completing an apparent recapture sequence.'),
 [
  ('An exchange changes more than the score', '''When a piece leaves the board, a line may open through its former square. A rook exchange can remove the only back-rank defender; a bishop exchange can uncover a queen; a knight's departure can let a pawn advance with a threat. The book warns that a balanced count is not enough if the endpoint contains mate. After every exchange, mentally remove the captured piece and move the capturer to its real destination. Do not leave a ghost defender on the old square. Then scan checks against both kings before continuing the expected series of recaptures.'''),
  ('Inventory of the original demonstration', '''White has king g1, queen d2 and rook d3. Black has king g8, queen a5, rook d8, and pawns f7, g7 and h7. The pawns shelter the king from the front but occupy its flight squares. White can exchange rooks on d8 with check. Black's queen can recapture from a5 along b6-c7-d8. That route is important: she ends up on the very square White's queen can reach along the open d-file. The combination therefore cannot be evaluated by saying that one rook was exchanged for another and nothing changed.'''),
  ('Follow the line through its endpoint', '''After Rxd8+ Qxd8, White plays Qxd8 mate. The last queen reaches the eighth rank, and the king has neither a safe flight square nor a way to capture or block the queen. Before revealing that final move, inventory the remaining pieces: both rooks are gone, Black's queen is on d8, and White's queen is on d2 with an unobstructed file. In this constructed position, the queen recapture is Black’s only legal answer to the first check. Verify that the king’s exits are blocked or attacked and that no other interposition is possible. The board exercise starts after that forced recapture has occurred.'''),
  ('The opponent may break the sequence', '''A player is not required to recapture just because the opponent has captured. They may check, attack the queen, create a mate threat, or capture a different loose piece. This is why counting an entire exchange ladder as automatic can fail. When you calculate a tempting pawn capture, inspect whether your own attacking pieces are exposed to counterattacks. In the book, attacks against the attackers themselves overturn an apparently favorable pawn count. For practical play, perform one extra scan at each turn: is there something stronger than the expected recapture? Only after that scan should you trust the material arithmetic.'''),
 ],
 [example('Original illustration: the expected recapture exposes mate', P['exchange'], ('Rxd8+','Qxd8','Qxd8#'),
          ('White: Kg1, Qd2, Rd3. Black: Kg8, Qa5, Rd8, f7/g7/h7. Predict the d-file after the two rooks disappear.',
           'White exchanges rooks on the back rank with check.',
           'Black chooses the queen recapture. It leaves the queen on the open d-file and removes the last rook.',
           'White captures the queen with mate. The king is checked on the eighth rank and its own pawns occupy the seventh-rank exits.'))],
 ('Do not leave exchanged pieces in your mental picture.', 'Do not assume recapture is forced unless every legal alternative has been checked.'),
 [check('exchange-end','Why does an equal rook exchange matter here?',
        ('It clears the d-file and removes a back-rank defender',True,'The resulting board allows a decisive queen capture with mate.'),
        ('Rooks become less valuable after moving',False,'Piece values did not change; lines and king safety did.')),
  check('exchange-between','What should you test before assuming the opponent will recapture?',
        ('Checks, threats, and captures elsewhere',True,'An intermediate move can change the whole sequence.'),
        ('Only whether the recapture gains material',False,'A stronger forcing move may take priority over material.'))],
 ('Remove every exchanged piece mentally.','Inspect newly opened lines.','Allow the opponent to interrupt the exchange sequence.'))

_add('mobilize', (137,137),
 ('Count future attacks together with their time cost.', 'Distinguish direct pressure from an x-ray behind another piece.'),
 [
  ('Security is a moving comparison', '''A pawn defended once against one attack may be safe now and unsafe two moves later. The book extends counting to pieces that can join the struggle. Ask which of your pieces can attack the target in one move, which need two moves, and how the opponent can reinforce it during the same time. Alternate the imagined moves; do not bring three attackers into place while freezing the defender. This is useful for an isolated pawn, an outpost, or a square you want to occupy. It converts the vague idea of pressure into a concrete contest of arrival times.'''),
  ('Read this board before calculating', '''Our original illustration has White's king g1, rooks d1 and c2, bishop e3 and knight f3. Black has king g8, rook d8, bishop f8, knight c5 and pawn d4. The target is d4, not the black king. White's rook from c2 can join the d-file with Rcd2; the notation identifies which rook moves because the d1-rook could also move to d2. Black can bring the knight to e6, where it attacks d4. White can then put the bishop on f2, while Black brings the bishop to g7. Both sides are improving their access to the same pawn.'''),
  ('Direct defenders and batteries differ', '''After the rooks double, the front rook on d2 attacks along the d-file. The rear rook on d1 is blocked by its own partner, so it is not currently a second direct attack on d4. It supplies an x-ray: once the front rook moves or is exchanged, the rear rook's line can become open. Count that future support in the sequence, not as permission for two simultaneous captures. Similarly, a bishop behind an occupied diagonal may become relevant only after an exchange. Before advancing each replay move, identify the exact intervening squares between the new piece and d4.'''),
  ('Pressure does not force an immediate capture', '''The replay ends with pieces arranged around d4. It does not claim that White can now win the pawn by any capture, or that Black was forced to choose these developing moves. You must still calculate values, move order, and intermediate checks before taking. Black might challenge an attacker, move the pawn, or improve the king instead. A premature pawn advance can also worsen its support by moving beyond its defenders. In your own games, count available reinforcements for both sides and compare the resulting structure before committing. A move that improves pressure while retaining options may be more useful than an immediate, unverified capture.'''),
 ],
 [example('Original illustration: both sides reinforce d4', P['mobilize'], ('Rcd2','Ne6','Bf2','Bg7'),
          ('White: Kg1, Rd1/Rc2, Be3, Nf3. Black: Kg8, Rd8, Bf8, Nc5, d4. Predict one new attacker and one new defender before moving.',
           'The front rook joins the d-file. The d1-rook is behind it, supplying a potential x-ray.',
           'The knight defends d4 from e6.', 'The bishop on f2 points through e3 to d4.',
           'The bishop on g7 points through f6 and e5 to d4. This is an illustrative reinforcement sequence, not a forced win.'))],
 ('A piece behind a friendly blocker is not yet a direct attacker.', 'Give the defender a move for every move used to increase pressure.'),
 [check('mobilize-time','You need three moves to add three attackers. What must you include?',
        ('Three opportunities for the opponent to respond',True,'Reinforcement must be calculated in alternating turns.'),
        ('Only your final formation',False,'The opponent can reinforce, exchange, or create a counterthreat while you prepare.')),
  check('mobilize-xray','Why is Rd1 not a second direct attack while Rd2 stands in front?',
        ('The front rook blocks its line',True,'The rear rook becomes active after the file clears.'),
        ('Rooks cannot cooperate on a file',False,'Doubled rooks cooperate very well, but their current lines still obey blocking rules.'))],
 ('Count arrivals, not only current attacks.','Alternate attacks and reinforcements.','Calculate the capture before converting pressure into action.'))

_add('wandering-square', (137,139),
 ('Recognize the strength of widely separated passers.', 'Use the wandering square as a pattern with conditions.'),
 [
  ('One king, two remote jobs', '''Two passed pawns on distant files can defeat a lone king without help from their own king. Chasing one gives the other time to advance beyond reach. The defender's difficulty is not simply that there are two pawns; it is the distance between their threats and the number of moves remaining to promotion. Two neighboring pawns often protect one another by direct attacks. Widely separated pawns may protect one another indirectly: capturing the first leaves the king outside the second pawn's square. The book studies both their defensive independence and their power to advance on their own.'''),
  ('Draw the common square', '''For two same-rank passers, use their file separation as the side of a square extending toward promotion. Imagine black pawns e6 and h6: the common square has corners e6, h6, h3 and e3. As the pawns move, this square changes its location, hence the name wandering square. If the corresponding common square reaches or passes the promotion rank, the pattern suggests that the king cannot stop both. This is a useful distance shortcut, not a universal theorem that ignores the king's actual position. An immediate pawn capture or a critical change of move order must be checked first.'''),
  ('Advance away from the king', '''The practical idea is to push the pawn farther from the enemy king. When the king shifts toward it, the other pawn becomes the distant danger. Our original example uses black pawns b4 and h4 against a white king on e3, with the black king safely on a8. Black starts with ...h3. White's illustrative reply Kf3 moves toward the h-pawn, and ...b3 sends the other pawn toward b1. Before each arrow, redraw the square of the pawn that the king is not approaching. This makes the indirect protection visible instead of treating two passers as automatically invincible.'''),
  ('Do not overclaim from a sample race', '''The shown king route is one legal illustration, not the only defensive try. It demonstrates how a distant pawn promotes while the defender is occupied elsewhere. To claim that a particular position is won against every defence, inspect captures, pawn attacks, king interference and the side to move. Equal-rank diagrams are easier than staggered pawns because both distances begin alike. If one pawn has already advanced, use separate promotion counts as well as the common-square picture. In practical play the shortcut tells you which pawn push to investigate; the final check confirms that you have not allowed a capture that removes the second threat altogether.'''),
 ],
 [example('Original illustration: the threat switches wings', P['wandering'], ('h3','Kf3','b3','Kf2','b2','Kf3','b1=Q'),
          ('Black: Ka8, b4 and h4. White: Ke3. Black to move. Compare the king’s routes to the two promotion files.',
           'The h-pawn advances; Black retains a distant second passer.',
           'White heads toward the h-file in this sample defence.',
           'Black now advances on the opposite wing.', 'The king still cannot reach the b-file in time.',
           'The b-pawn threatens promotion next turn.', 'This king move cannot stop b1.',
           'Black promotes safely. The queen is far from the white king and cannot be captured immediately.'))],
 ('Check the king’s starting square before applying the common-square pattern.', 'A sample line illustrates the mechanism; it does not list every defence.'),
 [check('wandering-jobs','Why can separated pawns protect one another without touching?',
        ('Capturing one may put the king outside the other’s square',True,'The defence is based on time and distance rather than a direct pawn attack.'),
        ('Pawns attack other pawns on the same rank',False,'Pawn attacks are diagonal, one rank forward.')),
  check('wandering-push','Which pawn push is often the useful candidate?',
        ('The pawn farther from the enemy king',True,'It creates the threat that demands the longest defensive journey.'),
        ('Always the pawn on the left edge of the screen',False,'Board orientation has no strategic meaning; king distance matters.'))],
 ('Compare two promotion threats.','Push away from the defending king when the position supports it.','Verify the pattern with captures and move order.'))

_add('separated-exceptions', (138,140),
 ('Test immediate captures before using the wandering square.', 'Recognize tempo and mobility exceptions.'),
 [
  ('A rule cannot protect a pawn already capturable', '''The wandering square is most useful when both pawns survive long enough to create threats. If the king can remove one immediately, the position becomes a single-pawn race and must be assessed again. In our original example White's king b4 can capture Black's pawn c3; Black's other pawn is on a3 and its king on h8. The same two pawns look dangerous when it is Black's move, because advancing a3 first changes how much time the white king has. Always read the side-to-move indicator before applying any geometric shortcut.'''),
  ('Count through the promotion capture', '''With White to move, Kxc3 removes one threat. Black's ...a2 looks close to success, but White reaches b2, from which a1 is controlled. The pawn can promote with check, yet Kxa1 then captures the unprotected new queen. The board is drawn because only kings remain. Before advancing the replay, count the king's two jobs separately: one capture on c3, then one move to b2. Notice that the king does not need to reach a1 before promotion; controlling a1 from b2 is sufficient. Requiring it to stand on the queening square would produce a false losing assessment.'''),
  ('Change the turn and reconsider', '''If Black starts with ...a2, White cannot use the same sequence with the same timing. For example, Kxc3 then allows ...a1=Q+ while the white king is still on c3 and cannot capture the queen. That branch demonstrates the cost of the missing tempo; it is not a complete enumeration of White's alternatives. The book also points out that unevenly advanced pawns and certain closely spaced pawns near promotion demand special care. When a theorem's assumptions are uncertain, switch to a short concrete line. A three-move verification is often easier than remembering a long list of exceptions.'''),
  ('Waiting moves are part of the position', '''A pair of pawns may hold a king at bay as long as their own king has harmless waiting moves. If that king is immobilized, the pawn side may be forced to push a pawn at the wrong moment and lose it. This is zugzwang: having to move makes the position worse. Conversely, a defender with a useful waiting square may compel an overextension. The book's blocked-wing examples show why counting available moves matters as much as counting distance. In your games ask which pieces can move without changing the essential position, and whether a pawn move is irreversible. Never assume that a player can pass a turn.'''),
 ],
 [example('Original illustration: White catches both threats', P['exceptions'], ('Kxc3','a2','Kb2','a1=Q+','Kxa1'),
          ('White: Kb4. Black: Kh8, a3 and c3. White moves first. Predict the route to control a1 after taking c3.',
           'The king removes c3 immediately; only one pawn remains.',
           'Black advances the survivor toward promotion.', 'The king reaches b2 and controls a1.',
           'The pawn promotes with check, but has no support.', 'White captures the queen. The game is drawn with kings only.')),
  example('Original illustration: giving Black the first move changes the branch', custom({'b4':'K','h8':'k','a3':'p','c3':'p'},turn='b'),
          ('a2','Kxc3','a1=Q+'),
          ('Same placement, Black to move. Predict whether the old Kxc3 plan still catches a1.',
           'Black advances before the white king has captured anything.',
           'White repeats the old capture, but is now a tempo behind.',
           'The queen appears with check while the king is still on c3. It cannot be captured.'))],
 ('The side to move is part of the position.', 'Check mobility and waiting moves before assuming that pawns can hold their formation forever.'),
 [check('separated-turn','What changed between the two replays?',
        ('Only the side to move, which changes the timing',True,'Identical piece placement can produce different tactical opportunities.'),
        ('The direction of Black’s pawns',False,'Black’s pawns still move toward rank one.')),
  check('separated-wait','Why can immobilizing the pawn side’s king matter?',
        ('It may force a weakening pawn move',True,'With no safe waiting move, the pawn formation may have to change.'),
        ('It lets the defender make two moves in a row',False,'Moves still alternate; zugzwang works because passing is unavailable.'))],
 ('Remove immediate captures from the calculation first.','Recount when the turn changes.','Include the supply of waiting moves.'))

_add('key-squares', (140,142),
 ('Locate critical squares for an ordinary passed pawn.', 'Use the king to secure the next stage of promotion.'),
 [
  ('Aim for a destination that guarantees progress', '''A critical or key square is a square whose occupation by your king secures promotion in the basic king-and-pawn-versus-king ending, subject to the pawn not being immediately capturable. For a white pawn on e2, the important squares are d4, e4 and f4: two ranks ahead, on the pawn's file and the adjacent files. For b3 they are a5, b5 and c5; for b4 they are a6, b6 and c6. These destinations explain why bringing the king ahead of the pawn is often more useful than simply pushing the pawn toward the last rank.'''),
  ('The target moves with the pawn', '''When a pawn advances, its critical squares change. A king placed well for e2 may not yet be placed well for e3. Before pushing, identify the new target squares and ask whether your king can still occupy one. Once an ordinary pawn reaches its fifth rank, the defender has less space: both the three squares one rank ahead and the three two ranks ahead become critical, when they exist on the board. For a white b5-pawn, these are a6/b6/c6 and a7/b7/c7. Rook pawns require a separate corner rule and will be considered in the next lessons.'''),
  ('Reach the vulnerable side', '''Our replay begins with White's king e1 and pawn e2 against Black's king e8. The route Kd2-d3-e4 reaches a critical square. Black's shown approach through e7 and d6 cannot prevent that arrival. Before advancing Ke4, identify all three key squares and check that e4 is not adjacent to the black king on d6. A king cannot claim a key square by stepping into check. If the defender is nearer one side, the attacker may need to approach the farthest key square instead. Choose the destination first, then calculate a legal route to it.'''),
  ('The defender guards access, not the pawn alone', '''Black's objective is to keep the attacking king away from every usable key square. Opposition is one method: place the king so the attacker must yield a route or spend a pawn tempo. This is why the same king placement can be winning or drawn depending on whose turn it is. The key-square rule supplies an endpoint for calculation, so you need not mentally promote the pawn from every candidate line. But first verify that the endpoint really fits the basic ending: no extra checking piece, no immediately lost pawn, and no rook-pawn exception. In your own games label the targets before deciding which king move feels natural.'''),
 ],
 [example('Book diagram 237 route: secure e4 before pushing e2', P['keys'], ('Kd2','Ke7','Kd3','Kd6','Ke4'),
          ('White: Ke1 and e2. Black: Ke8. White moves. The targets are d4, e4 and f4; predict a three-move route.',
           'White heads toward the central key squares.', 'Black approaches the pawn’s future route.',
           'White keeps e4 available.', 'Black cannot attack e4 from d6.',
           'The king occupies a critical square while the pawn remains on e2. The next lesson considers when to advance it.'))],
 ('Recompute the critical squares after a pawn push.', 'Do not apply the ordinary-pawn rule unchanged to an a- or h-pawn.'),
 [check('keys-e2','Which are the basic critical squares for White’s e2-pawn?',
        ('d4, e4 and f4',True,'They are two ranks ahead, on the pawn’s file and its neighbors.'),
        ('d3, e3 and f3',False,'Those squares are generally not far enough ahead for an early ordinary pawn.')),
  check('keys-fifth','Why does a pawn on its fifth rank have more critical squares?',
        ('The defending king has less space near the last rank',True,'The three squares immediately ahead become sufficient as well.'),
        ('A fifth-rank pawn may move two squares',False,'The double move is available only from the pawn’s starting rank.'))],
 ('Locate the key squares before choosing the route.','Get the king ahead when necessary.','Update the target after every pawn move.'))

_add('pawn-timing', (142,144),
 ('Use a pawn move to transfer the turn at the right moment.', 'Keep control of the pawn’s next critical squares.'),
 [
  ('A pawn move changes time and territory', '''A pawn push has two effects that must be assessed together. It brings promotion closer, and it changes whose turn it is without moving the king. In some endings that second effect is the decisive one: the defender must leave an important square while your king retains its useful position. In others, pushing abandons a favorable reserve move and leaves your king short of the new critical squares. Never treat a legal pawn advance as automatically progress. First identify what the king controls now, what it will need after the push, and which reply the defender will have.'''),
  ('Compare two nearby diagrams', '''The book contrasts White's king b6 and pawn c6 against a black king c8 with White's king c6 and pawn c5 against the same defender. In the first position, whose turn it is matters greatly. In the second, the king is already on a critical square for the fifth-rank pawn and White can arrange a useful pawn tempo. Our replay uses the second position. White plays Kb6, Black answers ...Kb8, and c6 passes the move back. The king remains on b6 while the pawn now controls b7 and d7, restricting the defender's options.'''),
  ('Calculate the entry square, not just the push', '''After c6, the shown reply ...Kc8 allows c7. The black king must leave c8, and White can then occupy b7, protecting c8 for promotion. Before advancing the replay at c6, name the squares attacked by each king and by the pawn. After c7, note that the pawn controls b8 and d8, so Black cannot simply shuffle along the back rank to either of those squares. The line demonstrates how pawn attacks and king opposition work together. The king's destination b7 is the real achievement; the pawn advance makes that destination available at the correct time.'''),
  ('Resist the urge to push every turn', '''At an earlier stage, moving the king farther ahead may be necessary before the next pawn push. At a later stage, a careless king move may stalemate the defender if the pawn blocks its only legal square. Keep asking three questions: can the pawn be captured, can my king reach the new key square, and does the defender still have a legal move if I am trying to win? These questions also help defence. If you cannot save a pawn, you may be able to force its opponent to advance before the attacking king is ready. The book's detailed king routes are examples of timing a concrete target, not a blanket instruction always to take opposition.'''),
 ],
 [example('Book diagram 239a: use the c-pawn’s reserve move', P['timing'], ('Kb6','Kb8','c6','Kc8','c7','Kd7','Kb7'),
          ('White: Kc6, c5. Black: Kc8. White moves. Predict how a pawn move can preserve the king’s position while changing the turn.',
           'White approaches b7 from b6.', 'Black takes opposition and guards the entry square.',
           'The pawn move transfers the turn without moving the white king.', 'Black returns to c8 in the shown defence.',
           'The pawn takes away b8 and d8 from the black king.', 'The king leaves the back rank; this is one legal defence.',
           'White reaches b7 and controls c8. The pawn’s promotion is secured.'))],
 ('A pawn’s critical squares move when the pawn moves.', 'Check stalemate before celebrating a tightly confined defending king.'),
 [check('timing-pass','What useful effect does c6 have after Kb6 ...Kb8?',
        ('It gives Black the move while the king stays on b6',True,'The spare pawn tempo disrupts the defender’s hold on the entry squares.'),
        ('It permits White to move the king again immediately',False,'Black must still make a move between White’s turns.')),
  check('timing-stale','The defender has no legal move and is not in check. Have you won?',
        ('No, that is stalemate',True,'A pawn ending can be spoiled by removing all legal moves without giving check.'),
        ('Yes, because the defender is trapped',False,'Checkmate requires check; a trapped but unchecked side is stalemated.'))],
 ('A pawn move can be a reserve tempo.','Secure the next key squares before pushing.','Watch for stalemate at the edge.'))

_add('rook-pawn', (143,146),
 ('Recognize the special promotion corner of a rook pawn.', 'Evaluate structural changes after pawn exchanges or sacrifices.'),
 [
  ('The edge removes the king’s outflanking route', '''An a-pawn or h-pawn is a rook pawn. Unlike a central pawn, it has only one neighboring file on the board. If the defending king reaches the promotion corner and cannot be driven away, extra space on the other side does not exist. This is why many positions that win with a b-pawn draw with an a-pawn. For White's a-pawn, the key supporting square is b7: from there the white king controls a8 and excludes the defending king from the corner. Mirror the geometry for an h-pawn, whose corresponding key square is g7.'''),
  ('Secure the corner before counting a win', '''Our original exercise gives White a king on c6 and pawn a6, with Black's king d8. Kb7 takes control of a8 before pushing. In the illustrative line, Black approaches through e7 and d6 while the pawn promotes. Compare the separate corner demonstration: White starts with king a5 and pawn a6 against a black king a8. After Kb6, Black uses b8. White’s a7+ drives the king back to a8, but Ka6 then removes every legal move without giving check. The result is stalemate, not a win.'''),
  ('An exchange can change the pawn’s identity', '''Suppose you own a b-pawn and the opponent offers an a-pawn capture. After bxa3, your surviving pawn is a rook pawn. Winning an enemy pawn may therefore leave a worse winning prospect than declining the capture with b3. The book uses this transformation to explain king routes that initially look unnecessarily indirect. Calculate the final file, not just the number of pawns remaining. From the defender's perspective, offering an exchange that leaves a rook pawn can be a drawing resource. From the attacker's perspective, preserving the ordinary pawn may justify spending time on a different king route.'''),
  ('Sometimes a forward pawn must be sacrificed', '''Doubled pawns illustrate another structural lesson. A pawn near promotion may obstruct its own king or deprive the defender of useful moves, while a rear pawn has better critical-square geometry. The book shows a forward b-pawn being promoted and sacrificed so the king can support the rear pawn. This is not a rule to throw away advanced pawns: calculate which pawn remains, whose move it is, and which key square your king can occupy afterward. Before advancing either replay here, compare the promotion corner, the supporting king's square, and the defender's legal moves. Those three facts matter more than how impressive the pawn's rank looks.'''),
 ],
 [example('Original illustration: b7 secures the promotion corner', P['rook-pawn'], ('Kb7','Ke7','a7','Kd6','a8=Q'),
          ('White: Kc6 and a6. Black: Kd8. Predict which king square controls the corner before pushing.',
           'The king reaches b7 and protects a8.', 'Black moves away in this illustrative defence.',
           'The pawn advances under king protection.', 'The defending king cannot reach a8 in time.',
           'White promotes safely. The route was secured before the pawn moved.')),
  example('Original illustration: the corner defence ends in stalemate', custom({'a5':'K','a6':'P','a8':'k'}), ('Kb6','Kb8','a7+','Ka8','Ka6'),
          ('White: Ka5, a6. Black: Ka8. The defender occupies the promotion corner. Predict which flight square remains after Kb6.',
           'White approaches but still cannot drive the defender away permanently.',
           'Black uses b8, preserving access to the corner.',
           'The pawn checks the king on b8 and takes away that flight square.',
           'Black returns to the promotion corner.',
           'White closes the remaining seventh-rank flights without giving check: stalemate. A more advanced pawn has not solved the corner problem.'))],
 ('Do not treat a rook pawn like an ordinary central pawn.', 'After an exchange, identify the remaining pawn’s file and key squares afresh.'),
 [check('rook-key','Which king square secures White’s a-pawn promotion corner in the basic model?',
        ('b7',True,'The king controls a8 and keeps the defender out of the corner.'),
        ('h7',False,'A distant king on h7 cannot protect a8.')),
  check('rook-file','Why might bxa3 spoil a winning plan?',
        ('It turns the surviving b-pawn into a rook pawn',True,'The corner defence may then become available.'),
        ('Capturing backward is illegal for every pawn',False,'White’s b-pawn can capture forward onto the a-file; the issue is the resulting ending.'))],
 ('Rook pawns have special corner geometry.','Check the pawn’s file after exchanges.','A nearer pawn is not always the better pawn to preserve.'))

_add('blocked-pawns', (146,148),
 ('Locate critical squares beside an immobilized pawn.', 'Separate winning the enemy pawn from converting the remaining pawn.'),
 [
  ('Blocked pawns create lateral targets', '''When White's pawn d4 faces Black's pawn d5, neither can advance straight ahead. The struggle becomes a race for king entry squares beside the pawns. For attacking the black pawn d5, the book identifies a5/b5/c5 and e5/f5/g5 as critical squares for White's king. For attacking White's d4-pawn, Black's equivalent targets lie on rank four. These differ from the squares in front of a passed pawn because the immediate objective is different: capture a stationary enemy pawn first, then escort the survivor. Say which pawn you are attacking before naming its critical squares.'''),
  ('Enter from the side and outflank', '''The source position contains White's king h4 and pawn d4 against Black's king e8 and pawn d5. White begins Kg5, claiming a critical square beside d5. The king then works around the defender through f5, f6, e5 and e6. In the shown line, Black cannot keep the white king away from the pawn forever. Before each king move, check adjacency and identify the intended next entry square. The route is not a chase after the enemy king for its own sake. Every step is chosen to reach d5 from a side the defender cannot permanently cover.'''),
  ('The defender changes its goal in time', '''Black can foresee that d5 will fall. Rather than making a hopeless attempt to protect it at any cost, Black uses ...Kc7 and then ...Kd7 to meet Kxd5 with opposition. White has won a pawn, but its own pawn is still on d4, and the king on d5 has not secured the necessary sixth-rank key squares. The basic resulting ending is drawn with accurate defence. This is a particularly useful beginner lesson: a material gain is an intermediate result. Evaluate the remaining position before deciding that the whole game has been won.'''),
  ('Sacrifices can select a better target', '''Later source examples use a knight or an advanced pawn as bait to create a favorable blocked-pawn ending. A sacrifice is sound only if the resulting king route actually reaches the relevant critical squares. An extra pawn on the fifth rank may make the capture decisive, whereas the same pattern one rank lower may draw. Before advancing the final Kxd5 in this replay, imagine both the pawn's new status as a passed pawn and the defender's reply ...Kd7. In your games, when losing a pawn is unavoidable, ask whether you can use the capture tempo to obtain opposition or guard the new key squares.'''),
 ],
 [example('Book diagram 248: the pawn falls, but the game is drawn', P['blocked'],
          ('Kg5','Ke7','Kf5','Kd6','Kf6','Kd7','Ke5','Kc6','Ke6','Kc7','Kxd5','Kd7'),
          ('White: Kh4, d4. Black: Ke8, d5. Identify the critical squares beside d5, then predict the position after the pawn is captured.',
           'White reaches a critical square on the fifth rank.', 'Black approaches the blocked pawns.',
           'White closes on the side of d5.', 'Black protects the pawn and opposes entry.',
           'White moves around the defender, retaining access to e5.', 'Black keeps the pawn covered from behind.',
           'White advances the lateral invasion.', 'Black shifts to c6; this is the source’s defensive route.',
           'White threatens to reach and capture d5.', 'Black prepares the final opposition rather than clinging to the pawn.',
           'White wins d5, leaving a passed pawn on d4.', 'Black takes opposition. The white king lacks the sixth-rank key squares for d4, so winning the pawn has not won the game.'))],
 ('Name the target pawn: blocked-pawn and passed-pawn critical squares differ.', 'Do not equate winning one pawn with winning the ending.'),
 [check('blocked-target','For White attacking a blocked black pawn on d5, where are the lateral critical squares?',
        ('On the fifth rank beside d5, up to three files away',True,'a5/b5/c5 and e5/f5/g5 are the book’s target squares.'),
        ('Only on d7',False,'That describes neither the lateral attack nor the set of blocked-pawn critical squares.')),
  check('blocked-defend','Why does Black choose ...Kd7 after Kxd5?',
        ('To prevent the white king from securing the remaining pawn’s key squares',True,'Black has switched from saving d5 to drawing the single-pawn ending.'),
        ('To recapture the white king',False,'Kings are never captured, and adjacent kings are illegal.'))],
 ('Blocked pawns are attacked from the side.','Evaluate the ending after the capture.','Change defensive goals before the pawn falls.'))

_add('distant-opposition', (148,151),
 ('Recognize direct, distant and diagonal opposition.', 'Use opposition to guard concrete entry squares.'),
 [
  ('Opposition is control of access', '''When kings face each other with one intervening square, the player who does not have to move is said to hold the opposition in the basic model. The moving king must step aside or use a pawn move, potentially conceding entry. The same idea can begin farther apart, with three or five intervening squares on a rank or file. This is distant opposition. It matters because the defender can preserve a matching answer as the attacker approaches. Do not confuse it with checking the enemy king: legal kings never attack one another.'''),
  ('Follow the approach one stage at a time', '''Our original geometry demonstration begins with White's king e1, pawn d3, and Black's king e7. The kings are far apart. After Kd2, ...Kd6 leaves three squares between them on the d-file. White shifts to e2 and Black mirrors with ...Ke6. Then Ke3 ...Ke5 reduces the distance to ordinary opposition with e4 between the kings. The pawn stays still so you can focus on the king relationship. Before advancing each black reply, identify the file and count the intervening squares. This replay teaches the geometry; it does not claim that every initial move or every king-and-pawn ending is drawn.'''),
  ('The real target can override the pattern', '''If the defender's job is merely to protect a few key squares, it may not need to mirror every distant king move. A small set of waiting squares may preserve all required replies more efficiently. Conversely, a pawn attack can make the visually corresponding square illegal. A passed pawn can also prevent the defender from taking opposition if that would leave its square. The book combines these constraints with opposition: the king must guard a blocked pawn's critical squares while remaining near a distant passer. Draw the targets first; only then decide which kind of opposition helps guard them.'''),
  ('Retreat can be the accurate defence', '''An attacker often wants to capture a pawn immediately, but the wrong approach can lose the opposition after the capture. A defender may deliberately retreat to meet the future capture from the correct distance. The source examples distinguish these timing details and show that moving the same king one rank changes the result. In practical play, do not choose a move solely because it produces an attractive kings-facing picture. Calculate the next entry attempt, the opponent's spare pawn moves, and the final pawn ending. Opposition is a means of reaching or denying key squares; it is not itself the objective of chess.'''),
 ],
 [example('Original illustration: distant opposition becomes near opposition', P['opposition'], ('Kd2','Kd6','Ke2','Ke6','Ke3','Ke5'),
          ('White: Ke1, d3. Black: Ke7. This is a geometry exercise. Predict matching king squares, without assuming that copying alone proves a result.',
           'White approaches on the d-file.', 'Black leaves three intervening squares: d3, d4 and d5.',
           'White switches files while leaving the pawn unchanged.', 'Black preserves the distant relationship on the e-file.',
           'White closes the gap.', 'Black takes near opposition, with e4 between the kings. Evaluate the pawn targets separately.'))],
 ('Opposition has a purpose only in relation to entry squares and pawn play.', 'A pawn attack may forbid the square that symmetry suggests.'),
 [check('opposition-distance','How many intervening squares characterize distant opposition on one file here?',
        ('Three or five',True,'The odd number permits a matching approach toward near opposition.'),
        ('Exactly two',False,'That is not the ordinary distant-opposition relationship described here.')),
  check('opposition-purpose','What is the practical purpose of opposition?',
        ('Gain or deny entry to useful squares',True,'The king relationship serves the pawn-ending goal.'),
        ('Keep the kings in a symmetrical picture at any cost',False,'Symmetry may lose to a pawn push, an illegal square, or a second threat.'))],
 ('Recognize the geometry.','Identify the squares it protects.','Include pawn tempos and legal access.'))

_add('corresponding-squares', (152,152),
 ('Define a corresponding-square relationship from actual threats.', 'Avoid committing first in a mutual zugzwang.'),
 [
  ('A correspondence is an answer to a threat', '''Corresponding squares pair a useful attacking king square with a defensive king square that answers its threat. They need not face each other symmetrically. Direct opposition is a familiar special case, but blocked pawns often create irregular pairs. Begin by identifying the decisive invasion: which pawn will fall, which passer will run, or which promotion square needs protection? Then ask where the defending king must stand to answer that invasion. Work backward from those concrete tasks. Assigning matching numbers to squares without knowing what each square accomplishes is memorization rather than analysis.'''),
  ('Inventory the source position', '''White has king a4, pawns a6 and g5; Black has king b8, pawns b6 and g6. The g-pawns are blocked, while the a6 and b6 pawns can be attacked by kings from opposite sides. White's relevant attack square is b5; Black's is a7. If White goes Kb5 too soon, Black answers ...Ka7. White must then move away from the protection and pressure it wanted to preserve. The useful correspondence therefore concerns readiness to move to b5 or a7 at the right time, not a race to occupy either square immediately.'''),
  ('Retain the reply rather than rushing', '''The source's waiting route begins Kb4 ...Ka8, then Kc4 ...Kb8, and Kb4 ...Ka8 again. White remains able to answer ...Ka7 with Kb5. Black remains able to answer Kb5 with ...Ka7. Both sides have enough maneuvering space to keep that reply in reserve, so neither is forced to make the unfavorable commitment. Before advancing a waiting move, name the decisive square still reachable from the destination. That one-step reach is what makes the waiting square useful. A king move that looks equally quiet but loses access to b5 can concede the entire struggle.'''),
  ('Use correspondence as a compact calculation', '''Instead of calculating many long king shuffles, you can summarize them by the replies each side must retain. This is particularly useful with locked pawn chains, where the pawn structure will not change immediately. The method still needs updating if a pawn can move or be sacrificed. In your games, start with just one important pair; complicated systems arise by linking several such pairs. This lesson is a drawing example because both players have adequate waiting squares. The next lesson shows what happens when the attacker has a spare route and the defender cannot maintain the correspondence.'''),
 ],
 [example('Book diagram 258: preserve the critical reply', P['corresponding'], ('Kb4','Ka8','Kc4','Kb8','Kb4','Ka8'),
          ('White: Ka4, a6/g5. Black: Kb8, b6/g6. The relevant king squares are b5 and a7. Predict which waiting move keeps access to b5.',
           'White retains Kb5 without making that commitment first.', 'Black retains ...Ka7 from a8.',
           'White still has a one-move route to b5.', 'Black still has a one-move route to a7.',
           'White returns to another useful waiting square.', 'Black preserves the matching reply. Neither side has been forced to break the correspondence.'))],
 ('Define the threat before labeling corresponding squares.', 'A waiting move must retain the necessary reply.'),
 [check('correspondence-meaning','What makes two squares correspond?',
        ('One is the required answer to the threat created by the other',True,'The relationship comes from concrete defensive tasks.'),
        ('They have the same color',False,'Square color alone does not define the king’s required response.')),
  check('correspondence-first','Why does White avoid Kb5 immediately?',
        ('Black can answer ...Ka7 and leave White to move in an unfavorable position',True,'The timing of the attack matters more than being first to touch the target.'),
        ('Kb5 is an illegal king move',False,'It is legal, but strategically premature in this position.'))],
 ('Find the decisive invasion square.','Identify its required defensive answer.','Preserve access until the opponent must yield.'))

_add('triangulation', (152,154),
 ('Explain why a triangular king route changes the move order.', 'Connect triangulation to the defender’s missing corresponding square.'),
 [
  ('Returning can accomplish something', '''Triangulation is a three-move king circuit that returns to the starting square while the defender has used an even number of moves. The piece placement can be identical, but the side to move is reversed. This matters when the original position is favorable only if the opponent must move. A triangle is not automatically useful: each square on the route must be legal, the essential threats must remain, and the defender must lack a way to make an equally effective tempo maneuver. The book explains the mechanism through corresponding squares rather than treating a three-square shape as magic.'''),
  ('Read both threats in the source diagram', '''White has king d5 and pawns a5/c6; Black has king c8 and pawn a6. White can threaten Kd6, supporting the c-pawn's advance, or Kc5, preparing Kb6 and the capture of a6. To answer Kd6, Black needs access to d8; to answer Kc5, Black needs access to c7. The starting king squares d5 and c8 therefore form another correspondence. Before advancing, name both threats. If you see only the c-pawn, the king's roundabout route will seem pointless; the queenside pawn target is the second demand that restricts Black's waiting moves.'''),
  ('Watch the missing waiting square', '''White begins Kd4 and Black answers ...Kb8 in the replay. White now plays Kc4, keeping both c5 and d5 available. Black would like another square that preserves all corresponding replies, but b7 is forbidden by the pawn c6. In the shown line Black returns to c8. White then plays Kd5, restoring the initial placement with Black to move. On ...Kc7 White chooses Kc5; on ...Kd8 or ...Kb8, White chooses Kd6. The defender has to yield one target. Pause at the fifth ply and verify that only the side to move has changed.'''),
  ('Extend the idea without overgeneralizing', '''The source's next position uses several linked pairs: c5/d7, b5/d6, and c4/e7. White reaches b4, from which all three white destinations are accessible, while the analogous black square is unavailable. This is the same principle in a more complex shape: compare the sets of useful next moves, not merely the distances between kings. In your games, first determine which side should have the move in the critical position. Then search for a safe waiting circuit or pawn tempo. A random king triangle that abandons a pawn, permits a breakthrough, or gives the defender the same flexibility has achieved nothing.'''),
 ],
 [example('Book diagrams 259–259a: return with Black to move', P['triangle'], ('Kd4','Kb8','Kc4','Kc8','Kd5','Kc7','Kc5'),
          ('White: Kd5, a5/c6. Black: Kc8, a6. Predict both Kd6 and Kc5 threats before following the triangle.',
           'White leaves d5 but retains access to c5 and d5.', 'Black uses a corresponding waiting square.',
           'White changes waiting squares without abandoning either route.', 'Black returns to c8; b7 is attacked by c6.',
           'The original placement is restored, but Black must now move.', 'This defence keeps d6 under control but yields the queenside entry route.',
           'White answers the chosen defence by approaching b6 and a6. Against ...Kd8, the intended answer would instead be Kd6.')),
  example('Book diagram 260: one square offers three useful choices', custom({'c5':'K','d5':'P','e4':'P','h4':'P','d7':'k','c7':'p','e5':'p','h5':'p'}),
          ('Kb5','Kd6','Kb4','Ke7','Kc4','Ke8','Kb5','Kd7','Kc5','Ke7','Kc6','Kd8','d6','Kc8','Kd5'),
          ('White: Kc5, d5/e4/h4. Black: Kd7, c7/e5/h5. Target: occupy c6 and support d6. Predict why b4 offers more options than c4 immediately.',
           'White asks Black to defend from d6.', 'Black preserves the first required response.',
           'b4 gives access to b5, c5 and c4.', 'Black cannot match all three options and chooses e7.',
           'White occupies the corresponding square at a favorable moment.', 'Black retreats.',
           'White switches to the b5 route.', 'Black must answer the threat of c6.',
           'White restores the original c5 position with Black to move.', 'Black yields c6.',
           'The king reaches the desired entry square.', 'Black stays near the pawn’s route.',
           'The pawn advances with king support.', 'Black retreats behind the blockade.',
           'White returns to support the central advance; the important c6 invasion and d6 push have been achieved.'))],
 ('A triangle helps only if the opponent cannot preserve the same threats.', 'Compare side to move as well as piece placement.'),
 [check('triangle-change','What changes after Kd4 ...Kb8 Kc4 ...Kc8 Kd5?',
        ('The same pieces occupy the same squares, but Black moves next',True,'The tempo change is the purpose of the three-move circuit.'),
        ('White has gained a pawn already',False,'No capture occurred; the improved move order creates the future gain.')),
  check('triangle-b7','Why can Black not use b7 as a matching waiting square?',
        ('White’s c6-pawn attacks b7',True,'The pawn removes a geometrically convenient king square.'),
        ('Kings may never stand on the seventh rank',False,'The rank is legal in general; the pawn’s attack is the specific restriction.'))],
 ('Determine who should move in the critical position.','Preserve both threats through the circuit.','Look for the defender’s missing waiting square.'))

_add('pawn-majority', (154,155),
 ('Find the candidate passer in a pawn majority.', 'Calculate the exchanges and the defender’s restraining pawn moves.'),
 [
  ('A majority is a possibility, not a passer', '''Three pawns against two on one wing give a numerical majority. They do not automatically create a passed pawn, because the smaller group may restrain the larger one with a well-timed advance. A passed pawn has no enemy pawn ahead of it on its own file or either neighboring file. To create one, identify the candidate: often the pawn with no enemy pawn directly ahead on its file. Then organize its neighbors to support its advance and the exchanges that remove opposing pawns. The source gives two arrangements in which different pawns should lead.'''),
  ('Advance the candidate with support', '''Our original illustration has White's a2, b2 and c2 pawns against Black's a7 and b7 pawns; the kings are far away on h1 and h8. The c-pawn is the candidate because there is no black c-pawn. White begins c4, then supports its further advance with b4. The intended formation c5 and b5 permits c6; after ...bxc6, bxc6 leaves a white passer on c6. Name the capturing pawn's new file after each exchange. The pawn that eventually becomes passed need not be the same physical pawn that first led the operation.'''),
  ('Give the defender a plan too', '''Black is not obliged to wait while the majority advances. In the book, an early b4 can be met by ...b5, restraining the formation. After c4 ...a5, the tempting a3 may allow ...a4 and make b4 difficult. The constructive response is b3, then a3 and b4 when the concrete position permits. In another arrangement, the central b-pawn is the candidate and should lead instead. The reusable lesson is to inspect which pawn lacks a direct counterpart, how the neighbors support it, and which opposing pawn push can freeze the group before it reaches a favorable exchange.'''),
  ('Preserve useful pawn moves and calculate contact', '''The replay uses passive black king moves to show the mechanism cleanly. It is an illustrative plan, not a proof that every defence allows the same formation. Real positions require calculation as soon as opposing pawns touch. A single-square move can preserve a useful spare tempo or avoid giving the opponent a restraining advance; the entertainment exercises use precisely timed a3 and b3 to make this point. Before revealing c6, remove the b7-pawn mentally and place the white b5-pawn on c6 after the recapture. Confirm that no enemy pawn remains ahead on b-, c-, or d-files. Then assess whether kings or pieces can stop the passer.'''),
 ],
 [example('Original illustration: exchange to create a c-file passer', P['majority'], ('c4','Kh7','b4','Kh8','c5','Kh7','b5','Kh8','c6','bxc6','bxc6'),
          ('White: Kh1, a2/b2/c2. Black: Kh8, a7/b7. Black’s king waits in this illustrative plan. Predict which pawn can lead and which pawn will survive the final exchange.',
           'The candidate c-pawn advances first.', 'Black waits; active pawn defences need separate analysis.',
           'The b-pawn prepares support for c5.', 'Another illustrative waiting move.',
           'The candidate reaches the fifth rank.', 'Black again leaves the pawn structure unchanged.',
           'The support pawn comes alongside.', 'This waiting move permits the planned breakthrough.',
           'White offers the candidate pawn to remove b7.', 'Black accepts the exchange in this branch.',
           'The former b-pawn becomes a passed c-pawn. No black pawn ahead remains on b-, c-, or d-files.'))],
 ('A majority can be restrained if its pawns advance in the wrong order.', 'The final passer may be the supporting pawn after a capture changes its file.'),
 [check('majority-candidate','Why is c2 the candidate in this arrangement?',
        ('There is no black pawn ahead on the c-file',True,'Its neighbors can support exchanges against the remaining a- and b-pawns.'),
        ('A c-pawn is always stronger than an a-pawn',False,'The arrangement and support determine the candidate, not a permanent ranking by file.')),
  check('majority-survivor','Which white pawn survives on c6 after c6 ...bxc6 bxc6?',
        ('The pawn that had stood on b5',True,'The support pawn recaptures onto c6 and becomes the passer.'),
        ('The original c-pawn',False,'That pawn was captured by Black’s b-pawn in the intermediate move.'))],
 ('Identify the candidate passer.','Arrange support and calculate the contact moves.','Account for restraining advances and spare tempos.'))

_add('outside-passer', (155,156),
 ('Use a distant passer to divert the enemy king.', 'Improve the resulting promotion race before committing the diversion.'),
 [
  ('A passer can win by being captured', '''An outside passed pawn lies farther from the main pawn group than the opponent's passer or king. Its advance can force the enemy king away, letting your king capture pawns on the other wing. The pawn need not promote to accomplish its job. This is a diversion, and its value comes from what your king can do during the opponent's journey. Do not sacrifice it just because it is outside: calculate the counterplay after it falls. If the opponent also gains a fast passer, the resulting race may draw or even favor the defender.'''),
  ('Inventory and compare the two races', '''The book's diagram 264 gives White king e4, pawns a5, c4 and h2; Black king d6, pawns a6, e5 and g7. The c-pawn can distract the black king, after which White targets e5 and g7. Black will then head toward a5 and run its own a-pawn. An immediate c5+ ...Kxc5 Kxe5 produces a race in which both sides need eight further moves to promote along the described routes. Black moves next and promotes first with check on a1 against the king on g7. That check prevents White's apparent matching promotion and changes the assessment.'''),
  ('Prepare the winning race first', '''White improves the timing with h4 before giving up c4. This pawn move brings the future runner two squares closer while leaving the diversion available. In the shown branch Black plays ...g6, which also brings its pawn one square nearer the white king's capture route. Then c5+ ...Kxc5 Kxe5 begins the king raid. White captures g6 and promotes while Black's a-pawn is still on a3. The queen has time to stop it. Before advancing h4, count what useful action White has accomplished and what comparable improvement Black can make. The point is a productive waiting move, not waiting for its own sake.'''),
  ('The defender may decline the bait', '''Black need not capture c5 immediately. Other king moves require their own calculation, and the source discusses how White's improved race also matters there. The replay deliberately shows the direct capture branch so the diversion and the count are easy to follow. Check the opponent's best resistance before claiming a forced result in a new position. For your own games, compare three moments: before the diversion, after the king captures it, and after both sides have obtained their new passed pawns. If the final position is unfavorable, look for a useful preparatory pawn move or a different target before giving away the outside passer.'''),
 ],
 [example('Book diagram 264: prepare the h-pawn, then divert', P['outside'],
          ('h4','g6','c5+','Kxc5','Kxe5','Kb5','Kf6','Kxa5','Kxg6','Kb5','h5','a5','h6','a4','h7','a3','h8=Q'),
          ('White: Ke4, a5/c4/h2. Black: Kd6, a6/e5/g7. Predict the future h-pawn race before sacrificing c4.',
           'White saves a future pawn move while preserving the diversion.', 'Black’s pawn comes closer to White’s capture route in this branch.',
           'The c-pawn checks, inviting the king away from e5.', 'Black accepts the diversion; declining it requires a different branch.',
           'White captures the central pawn and heads for g6.', 'Black starts toward a5.',
           'The white king approaches g6.', 'Black captures the queenside pawn and obtains an a-pawn runner.',
           'White captures g6, clearing the h-pawn’s route.', 'Black clears the a-file for its pawn.',
           'The prepared h-pawn starts its shorter remaining sprint.', 'Black starts the a-pawn race.',
           'White is now two pushes from promotion.', 'Black is still three pushes from promotion.',
           'White threatens h8 next.', 'Black reaches a3, not a2 or a1.',
           'White promotes with time to stop the a-pawn. The preparatory h4 changed the race.'))],
 ('An outside passer is useful only if the resulting king raid or race works.', 'Count promotion checks before calling a race equal.'),
 [check('outside-purpose','What is the c-pawn’s job in this plan?',
        ('Pull the black king away so White can capture e5 and g6',True,'The pawn’s sacrifice creates time and access for the king.'),
        ('Promote on c8 in every variation',False,'In the shown branch it is deliberately captured on c5.')),
  check('outside-prep','Why play h4 before c5+?',
        ('It shortens the future promotion route without losing the diversion',True,'The quiet move improves the position that will arise after the sacrifice.'),
        ('It gives check to the black king',False,'h4 is quiet; its value lies in the future move count.'))],
 ('Evaluate what the diversion buys.','Count both resulting races.','Prepare a useful tempo before sacrificing the passer.'))

_add('short-games', (156,158),
 ('Track removed defenders and opened lines through a forcing attack.', 'Distinguish a historical continuation from a proof of the shortest mate.'),
 [
  ('Length is not the same as difficulty', '''The entertainment introduction contrasts long forced lines with positions containing many reasonable branches. A sequence of checks may be easier to visualize than three quiet moves with many alternatives. Do not measure your calculation skill only by the number of moves you can recite. Measure whether the moves are legal, whether you included the defender's strongest replies, and whether you evaluate the final board correctly. The two source games show how early king exposure creates forcing play. They are training material for visualization, not opening traps you should expect every opponent to cooperate with.'''),
  ('Schlechter: the h-file opens by removal', '''In Schlechter–Wolf, White has king e1, queen d1, rooks a1/h1, knights c3/f3 and bishop d3; Black has castled on g8 and just played ...f6. The center contains White's d4/e5 pawns and Black's d5/e6 pawns. White's h4-pawn and bishop d3 target the king's shelter. Ng5 invites ...fxg5; after Bxh7+ and ...Kxh7, hxg5+ opens the h-file for the rook on h1. Before each arrow, say which pawn or bishop has disappeared and why the rook now gives check. The displayed acceptance is a historical branch; Black was not forced to accept the knight sacrifice.'''),
  ('Calculate the king hunt to an actual endpoint', '''Rh8+ offers another rook to draw or drive the king onto vulnerable squares. In the game Black runs with ...Kf7, and Qh5+ ...g6 Qh7+ ...Ke8 Qxg6 is mate. The queen's final diagonal to e8 and the blocked escape squares are the endpoint, not the excitement of the first sacrifice. If Black instead captures the rook, the book gives a different continuation. Pause after Rh8+ and acknowledge that branch before following the played line. A sound calculation must account for alternatives; a replay can teach one branch deeply without pretending that the opponent had only one legal move throughout.'''),
  ('Alekhine: update the checking piece each turn', '''The second game reaches an exposed black king on h5, with White's queen g3, bishop f7, knight f3 and h3-pawn ready to cooperate. The final sequence changes checkers repeatedly: queen, pawn, knight, bishop, and finally the f-pawn. Keep a piece inventory instead of trying to remember only move sounds. The source also notes that an earlier attacking choice was not the fastest mate, an important reminder that a beautiful game can contain improvements. Study the provided finish as a concrete legal mating line. Then reset and predict each next checker before advancing, gradually increasing the number of plies you can visualize accurately.'''),
 ],
 [example('Schlechter–Wolf 1894: the accepted-sacrifice branch', P['schlechter'],
          ('Ng5','fxg5','Bxh7+','Kxh7','hxg5+','Kg8','Rh8+','Kf7','Qh5+','g6','Qh7+','Ke8','Qxg6#'),
          ('White’s active forces: Qd1, Rh1, Bd3, Nf3, h4; Black’s king is g8 behind h7/g7. Full board includes both armies. Predict how removing h7 and h4 can open the rook’s file.',
           'The knight moves to g5, offering material to open lines.', 'Black accepts; this reply is a choice, not a forced capture.',
           'The bishop removes h7 with check.', 'The king captures the bishop in this branch.',
           'The h-pawn takes on g5, opening the h-file so the rook gives discovered check.',
           'The king retreats to g8.', 'The rook invades h8 with check, offering another sacrifice.',
           'Black chooses to run to f7 rather than capture the rook.',
           'The queen joins from h5, checking along the diagonal h5–g6–f7.',
           'The pawn blocks on g6.', 'The queen checks along rank seven.',
           'The king retreats to e8.', 'The queen removes g6 and gives mate along g6-f7-e8.')),
  example('Alekhine–Amateur 1936: a changing cast of checking pieces', P['alekhine'],
          ('Qg4+','Bxg4','hxg4+','Kxg4','Nh2+','Kh5','Nf1+','Kg4','Be6+','Qxe6','f3#'),
          ('White: Ke1, Qg3, Bf7, Nf3, h3 plus the remaining opening army. Black: Kh5, Qf6, bishops c8/e7 and g6/h7 pawns among its remaining pieces. Predict each checker after the queen sacrifice.',
           'The queen checks from g4 and invites a capture.', 'The c8-bishop captures the queen on g4.',
           'White’s h-pawn recaptures with check on h5.', 'The king captures that pawn and moves onto g4.',
           'The knight checks from h2.', 'The king retreats to h5.',
           'The knight leaves h2, reopening the h-file for a discovered rook check.',
           'The king returns to g4 in the played branch.',
           'The bishop checks along e6-f5-g4.', 'Black’s queen captures the bishop to answer that check.',
           'The f-pawn gives mate. The king’s surrounding squares are occupied or attacked.'))],
 ('A played sacrifice acceptance is not necessarily forced.', 'Do not call a historical mating line the shortest without checking improvements.'),
 [check('short-open','Why does hxg5+ check in the Schlechter line?',
        ('It opens the h-file for the rook on h1',True,'The pawn’s departure uncovers the rook’s attack on the king.'),
        ('A pawn on g5 directly attacks h7',False,'A white pawn on g5 attacks f6 and h6, not h7.')),
  check('short-depth','Which is a better measure of calculation than raw move count?',
        ('Accurate legal moves, relevant defences, and a correct endpoint',True,'Depth is useful only when the line and its evaluation are sound.'),
        ('The number of sacrifices, regardless of replies',False,'An unsound sacrifice can make a line dramatic without making it correct.'))],
 ('Track removals and opened lines.','Identify alternatives at branch points.','Verify mate at the final board.'))

_add('knight-checks', (158,164),
 ('Anticipate knight checks and forks before choosing a king square.', 'Use restricted mobility to trap an apparently active defender.'),
 [
  ('A check can steal the decisive tempo', '''A king escorting a pawn may be one move from winning, yet a knight check can force it away and fork the pawn. Do not calculate only the pawn's distance to promotion. List the knight's legal checking destinations from its current square, then test whether your proposed king move makes one of them useful. The entertainment studies emphasize this characteristic battle between king and knight. A king move toward the center is not always best; a quiet edge square may deny the defender every effective checking tempo and preserve the pawn's advance.'''),
  ('Why the corner move works in the study', '''The source position has White's king g7 and pawn g6 against Black's king e3 and knight g2. White plays Kh8. The king stays close enough to support g7 while avoiding the checking patterns that spoil more natural routes. Our replay shows ...Nh4, g7, ...Nf5, g8=Q. These knight moves are illustrative resistance, not the only legal defence. Before revealing g7, count which squares a knight on h4 attacks: f3, f5, g2 and g6. It cannot both stop the advance and gain a useful check on h8 in this line. After promotion, check whether the new queen can be captured.'''),
  ('A different trap: immobilize before approaching', '''Another entertainment position contains White's king g1, bishop g5 and pawns b3/f6 against Black's king h7, knight b1 and pawns b7/e6. White gives up f6 by f7 ...Kg7 Be7 ...Kxf7, then plays Bb4. From b4 the bishop controls a3, c3 and d2, all the knight's available exits from b1. White can later bring the king through f2-e3-d3 to collect it. The route matters: walking along the first rank can allow pawn advances that create a saving knight check. The immediate lesson is to remove mobility before chasing a piece.'''),
  ('Mobility connects the humorous studies', '''The book's other playful positions use related ideas: a trapped bishop is kept from escaping, a king threatens mate to force a pawn move, and a triangle changes the turn before the final approach. They are tactical uses of the same calculation questions: what can move, what is forced, and which move creates a new escape? Do not assume that an apparently imprisoned piece remains trapped after a pawn capture. Before advancing either replay, list the defender's exits and checks, then update the list after every move. In your own games this habit prevents both premature celebrations and missed opportunities to save a restricted piece.'''),
 ],
 [example('Entertainment study 10: avoid the knight’s useful checks', P['knight'], ('Kh8','Nh4','g7','Nf5','g8=Q'),
          ('White: Kg7, g6. Black: Ke3, Ng2. Predict which king move avoids useful checking tempi while keeping the pawn supported.',
           'The king moves to h8, the source study’s precise solution.',
           'Black attacks g6 from h4 in this illustrative defence.',
           'The pawn advances out of the attack and remains protected by the king.',
           'The knight changes route, but does not control g8.',
           'White promotes safely. The knight on f5 cannot capture g8.')),
  example('Entertainment study 2: a bishop seals the knight’s exits', custom({'g1':'K','g5':'B','b3':'P','f6':'P','h7':'k','b1':'n','b7':'p','e6':'p'}),
          ('f7','Kg7','Be7','Kxf7','Bb4'),
          ('White: Kg1, Bg5, b3/f6. Black: Kh7, Nb1, b7/e6. Predict how the bishop could cover every on-board knight destination.',
           'White advances the pawn, drawing the black king toward it.',
           'Black blocks the pawn and prepares to capture it.',
           'The bishop heads toward b4; the pawn sacrifice serves the trapping plan.',
           'Black captures the pawn in the source line.',
           'The bishop controls a3, c3 and d2. The knight is immobilized, and White can organize the king’s approach.'))],
 ('A knight’s check can matter more than its material value.', 'After trapping a piece, check whether pawn changes or checking moves can reopen an exit.'),
 [check('knight-tempo','Why calculate the knight’s checks before choosing a king route?',
        ('A check may force the king away and win a promotion tempo',True,'The knight can change the timing even when it cannot stop the pawn directly.'),
        ('Knights can check from any nearby square',False,'Knight attacks follow precise jumps that must be enumerated.')),
  check('knight-cage','Which squares does Bb4 seal for the knight on b1?',
        ('a3, c3 and d2',True,'Those are all its on-board destinations, and the bishop controls each.'),
        ('b2 and b3 only',False,'Knights do not move straight along their file.'))],
 ('List checking jumps before moving the king.','Deny exits before chasing a restricted piece.','Recheck the cage whenever pawns move.'))

_add('opposition-puzzle', (160,163),
 ('Use opposition and outflanking to prepare a mating net.', 'Evaluate a pawn ending before exchanging the last rooks.'),
 [
  ('A playful restriction reveals a serious method', '''The source puzzle starts with White's king a1 and rook c1 against Black's king a8. White must mate while moving the rook only once, on the final move. The rook already cuts off the c-file, restricting the black king to the a- and b-files. The white king must reach b6 so Rc8 will be mate. Moving the rook early would solve a different task. Before advancing the replay, identify the target square and the rook's current barrier. This is an exercise in king maneuvering, not the normal fastest technique for every rook-versus-king ending.'''),
  ('Alternate opposition with outflanking', '''When the black king stands on the b-file, White takes opposition on that file. When Black moves to the a-file, White advances through the c-file, where its own rook does not obstruct king movement beyond c1. Thus Ka2 ...Kb8 Kb2 ...Ka8 permits Kc3. The pattern repeats at higher ranks. Each detour gains territory without allowing the defender to take a favorable opposition at the decisive moment. Pause whenever Black switches files and predict whether White should mirror on the b-file or advance by the c-file. The reason for the route is more useful than memorizing its twenty-one plies.'''),
  ('Verify the final mating net', '''After the white king reaches b6 and Black retreats to a8, Rc8 gives mate. The rook controls the eighth rank, and the white king controls a7 and b7. Black cannot capture the distant rook or block its line because it has only a king. The rook has remained on c1 through every earlier move. The displayed black choices are the source's principal defensive line; other king replies can shorten the route. The important invariant is that the white king uses opposition on the main file and outflanks when the defender leaves it.'''),
  ('Exchange decisions require the same calculation', '''The next entertainment example asks whether Black should exchange rooks. After ...Rxd1 Kxd1, the resulting pawn ending looks drawable if White follows the most direct king route. But White has Kc3, then Kd3 at the proper moment, obtaining useful opposition and invading. This is why a trade that looks materially equal can lose the game. Before exchanging the last active pieces, remove both rooks mentally, put the capturing king on its real square, and calculate the best king route for the opponent. The side losing the exchange of pieces may be gaining the exact tempo or access it needed for the pawn ending.'''),
 ],
 [example('Entertainment puzzle 7: only the final white move uses the rook', P['rook-puzzle'],
          ('Ka2','Kb8','Kb2','Ka8','Kc3','Kb7','Kb3','Ka7','Kc4','Kb8','Kb4','Ka8','Kc5','Kb7','Kb5','Ka7','Kc6','Kb8','Kb6','Ka8','Rc8#'),
          ('White: Ka1, Rc1. Black: Ka8. Goal: reach b6 with the king, then mate with the rook’s only move. Predict the first opposition square.',
           'White takes the distant opposition on the a-file.', 'Black moves to the b-file.',
           'White mirrors on the b-file and preserves the distance.', 'Black yields the b-file.',
           'White advances through c3, using the detour.', 'Black returns toward the b-file.',
           'White takes the b-file opposition at the next stage.', 'Black retreats to the a-file.',
           'White advances again on the c-file.', 'Black falls back to b8.',
           'White keeps distant opposition on the b-file.', 'Black yields to a8.',
           'White gains another rank via c5.', 'Black returns to b7.',
           'White takes near opposition on the b-file.', 'Black steps to a7.',
           'White outflanks via c6.', 'Black retreats to b8.',
           'White reaches b6, the target king square.', 'Black returns to a8.',
           'The rook moves for the first time and gives mate; the king covers a7 and b7.')),
  example('Entertainment example 8: inspect the pawn ending before exchanging', custom({'e2':'K','d1':'R','e3':'P','f4':'P','g6':'k','d6':'r','f5':'p'},turn='b'),
          ('Rxd1','Kxd1','Kf6','Kd2','Ke6','Kc3','Kd5','Kd3','Kd6','Kd4'),
          ('White: Ke2, Rd1, e3/f4. Black: Kg6, Rd6, f5. Black moves. Predict the king-and-pawn ending before accepting the rook trade.',
           'Black chooses the exchange that the source identifies as an error.',
           'White recaptures with the king, which is now free to approach the center.',
           'Black approaches the central entry squares.', 'White begins its king route.',
           'Black prepares opposition.', 'White uses the important detour through c3.',
           'Black approaches d5.', 'White takes opposition at the right moment.',
           'Black retreats in this branch.', 'White advances to d4 with the improved king position; the rook exchange must be judged by this resulting ending.'))],
 ('The one-rook-move restriction belongs to this puzzle, not to ordinary play.', 'Before exchanging, calculate the opponent’s best king route rather than the obvious one.'),
 [check('rook-puzzle-net','Why is Rc8 mate with White’s king on b6?',
        ('The rook controls rank eight and the king controls a7 and b7',True,'Together they cover the black king’s legal exits.'),
        ('A rook always mates from the eighth rank',False,'Without king support, the defender often has an escape on rank seven.')),
  check('rook-trade','What must you evaluate before exchanging the last rooks?',
        ('The resulting king positions, pawn structure, and side to move',True,'These determine whether the pawn ending is won, drawn, or lost.'),
        ('Only whether both rooks have equal material value',False,'Equal material traded can produce an unequal ending.'))],
 ('Choose the final king square.','Take opposition on the main file and outflank when allowed.','Evaluate the pawn ending before the trade.'))

_add('analysis-tree', (161,164),
 ('Separate a broad variation tree from a long forcing line.', 'Track the board accurately and evaluate each branch at a meaningful endpoint.'),
 [
  ('A branch table prevents mental mixing', '''A variation tree begins with a candidate move and divides whenever the opponent has a materially different reply. Calculate one branch to a useful endpoint, record its idea mentally, then reset to the common starting position. Do not carry a captured piece or moved pawn from one branch into another. The book's Shcherbakov–Yudovich example starts after White has taken a7 with a bishop. Black's quiet ...d6 attacks the queen on e5 and opens lines. It is a good test of breadth: White has several queen retreats, and each must be met by a concrete continuation.'''),
  ('Inventory the middlegame before tracing arrows', '''White has king g1, queen e5, rooks a1/d1, knight d5, bishop a7 and pawns a2/c2/f2/g2/h2. Black has king g8, queen f7, rooks e8/f8, knight e6, bishop c6 and pawns c7/d7/g7/h7. After ...d6, compare Qg3 with Qc3. Against Qg3, ...Bxd5 Rxd5 ...Nf4 attacks the rook and prepares a checking fork on e2. Against Qc3, ...Bxd5 Rxd5 ...c5 opens the seventh rank from f7 to a7 while also threatening f2. The same early capture leads to different follow-up tactics because the white queen occupies a different square.'''),
  ('A long line needs checkpoints, not just memory', '''The final source exercise begins with White's king g1, queen e2, rooks e1/f1 and bishops b3/d6 against Black's exposed king f7, queen c8, rooks d8/e8, bishop d7 and knights f6/g8. White's central pawns e5/f5 and Black's pawn e6 determine the opening of lines. Qh5+ invites ...Nxh5, then fxe6 opens attacks from the pawn and rook. Before advancing, identify the checker after every move and remove each captured unit mentally. The shown longest line is demanding, so stop at small checkpoints: after the queen sacrifice, after the rook lift, and before the quiet g3.'''),
  ('Train accuracy, then extend the horizon', '''The long replay reaches mate after g3 and Rh4, but g3 is not itself check. Black receives a move and the mating net must survive it; the displayed ...Rf8 is an illustrative legal reply at that stage. Do not infer that every move in a mating combination is forced merely because many earlier moves were checks. The book suggests revisiting these exercises later to measure improvement. Start by predicting two plies without moving pieces, verify them, then try four. Explain the final position in words. The transferable skill is reliable visualization and branch evaluation, not reciting a ten-move sequence whose defensive alternatives you have never examined.'''),
 ],
 [example('Shcherbakov–Yudovich 1957: the Qg3 branch', P['tree'],
          ('d6','Qg3','Bxd5','Rxd5','Nf4','Rd2','Ne2+'),
          ('Inventory: White Kg1/Qe5/Ra1/Rd1/Nd5/Ba7; Black Kg8/Qf7/Re8/Rf8/Ne6/Bc6, with pawns shown. Predict why ...d6 creates more than a pawn threat.',
           'The pawn attacks the queen and clears d7.', 'White chooses the g3 retreat.',
           'Black removes the knight on d5.', 'White recaptures with the rook from d1.',
           'The knight attacks the rook on d5 and prepares the checking fork on e2.', 'White saves the rook in the source branch.',
           'The knight checks the king on g1 from e2 while attacking the queen on g3. This is a concrete endpoint for the branch.')),
  example('Shcherbakov–Yudovich: the Qc3 branch', P['tree'], ('d6','Qc3','Bxd5','Rxd5','c5'),
          ('Reset to the same initial board; do not import the knight’s f4 move from the other branch. Predict the effect of ...c5 after exchanges.',
           'Black attacks the queen and opens d7.', 'White chooses c3 instead of g3.',
           'Black again exchanges the bishop for the knight on d5.', 'White’s rook recaptures.',
           'The c-pawn clears c7. Black’s queen now has an open seventh-rank line to a7 and a file attack on f2.')),
  example('Alekhine, Paris 1913: a long checking line and a quiet finish', P['long-mate'],
          ('Qh5+','Nxh5','fxe6+','Kg6','Bc2+','Kg5','Rf5+','Kg6','Rf6+','Kg5','Rg6+','Kh4','Re4+','Nf4','Rxf4+','Kh5','g3','Rf8','Rh4#'),
          ('White: Kg1, Qe2, Re1/Rf1, Bb3/Bd6, a2/c3/d4/e5/f5/g2/h2. Black: Kf7, Qc8, Rd8/Re8, Bd7, Nf6/Ng8, a4/b5/c6/e6/g7/h6. Predict the opened f-file after the queen sacrifice.',
           'The queen checks from h5, inviting the f6-knight away.',
           'The knight captures the queen and vacates f6.',
           'The f-pawn captures e6, checking with the pawn and opening the f-file rook’s attack.',
           'The king escapes to g6.', 'The bishop checks along c2-d3-e4-f5-g6.',
           'The king moves to g5.', 'The f-rook checks along the fifth rank.',
           'Black chooses the longest defensive route shown in the source.',
           'The rook checks on rank six while uncovering the bishop’s diagonal again.',
           'The king returns to g5.', 'The rook checks down the g-file.',
           'The king reaches h4.', 'The other rook checks along rank four.',
           'The knight from h5 blocks the rook’s line on f4.',
           'The rook captures that knight and checks along rank four.',
           'The king retreats to h5.', 'The quiet pawn move controls h4 and supports the planned mating rook.',
           'This legal rook move illustrates Black’s intervening turn; it does not break the mating net.',
           'The rook gives mate on h4, protected by g3. The other rook, bishop and pawn controls close the remaining flights.'))],
 ('Reset the board mentally before switching branches.', 'A quiet move inside a forcing sequence still gives the defender a turn.'),
 [check('tree-reset','What should you do before comparing Qc3 with Qg3?',
        ('Restore the common starting position mentally',True,'Otherwise pieces removed in one branch may incorrectly disappear in the other.'),
        ('Keep every move from the previous branch and continue',False,'The branches are alternatives, not one continuous game.')),
  check('tree-quiet','What must be checked after the quiet g3 in the long line?',
        ('Whether Black can prevent the threatened mate on its intervening move',True,'A threat is not a completed mate; defensive replies still matter.'),
        ('Nothing, because the previous moves were checks',False,'The earlier checks do not remove Black’s right to respond to a quiet move.'))],
 ('Calculate one branch to an evaluated endpoint.','Use piece inventories and checkpoints in long lines.','Revisit difficult exercises to measure accuracy, not just depth.'))
